mapper.select:
SELECT 
    RULE_VOUCHER_ID, RULE_CODE, RULE_NAME, RULE_TYPE, VOUCHER_TEMPLATE,
    EXECUTION_PERIOD, IS_ENABLED, BOOK_ID, TENANT_ID, VERSION,
    CREATE_TIME, UPDATE_TIME, CREATOR, UPDATER
FROM T_RULE_VOUCHER
WHERE IS_DELETED = 0

    AND RULE_CODE LIKE CONCAT('%', #{param.ruleCode}, '%')


    AND RULE_NAME LIKE CONCAT('%', #{param.ruleName}, '%')


    AND RULE_TYPE = #{param.ruleType}


    AND EXECUTION_PERIOD = #{param.executionPeriod}


    AND IS_ENABLED = #{param.isEnabled}


    AND BOOK_ID = #{param.bookId}


    AND TENANT_ID = #{param.tenantId}

ORDER BY CREATE_TIME DESC

SELECT * FROM T_RULE_VOUCHER
WHERE RULE_CODE = #{ruleCode}
AND BOOK_ID = #{bookId}
AND TENANT_ID = #{tenantId}
AND IS_DELETED = 0

    AND RULE_VOUCHER_ID != #{excludeId}

LIMIT 1

SELECT 
    RULE_VOUCHER_ID, RULE_CODE, RULE_NAME, RULE_TYPE, VOUCHER_TEMPLATE,
    EXECUTION_PERIOD, IS_ENABLED, BOOK_ID, TENANT_ID, VERSION,
    CREATE_TIME, UPDATE_TIME, CREATOR, UPDATER
FROM T_RULE_VOUCHER
WHERE RULE_TYPE = #{ruleType}
AND BOOK_ID = #{bookId}
AND TENANT_ID = #{tenantId}
AND IS_DELETED = 0
ORDER BY CREATE_TIME DESC

SELECT 
    RULE_VOUCHER_ID, RULE_CODE, RULE_NAME, RULE_TYPE, VOUCHER_TEMPLATE,
    EXECUTION_PERIOD, IS_ENABLED, BOOK_ID, TENANT_ID, VERSION,
    CREATE_TIME, UPDATE_TIME, CREATOR, UPDATER
FROM T_RULE_VOUCHER
WHERE EXECUTION_PERIOD = #{executionPeriod}
AND BOOK_ID = #{bookId}
AND TENANT_ID = #{tenantId}
AND IS_DELETED = 0
ORDER BY CREATE_TIME DESC

SELECT 
    RULE_VOUCHER_ID, RULE_CODE, RULE_NAME, RULE_TYPE, VOUCHER_TEMPLATE,
    EXECUTION_PERIOD, IS_ENABLED, BOOK_ID, TENANT_ID, VERSION,
    CREATE_TIME, UPDATE_TIME, CREATOR, UPDATER
FROM T_RULE_VOUCHER
WHERE IS_ENABLED = #{isEnabled}
AND BOOK_ID = #{bookId}
AND TENANT_ID = #{tenantId}
AND IS_DELETED = 0
ORDER BY CREATE_TIME DESC

